  "title": "A Food-Loving Cusco Afternoon",
  "summary": "We trade a packed schedule for a slower, tastier wander through Cusco, with a market-style lunch, a sweet museum stop, and a proper evening meal.",
  "stops": [
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "We begin in San Blas, where the little lanes and food stalls wake up the appetite before lunch.",
      "start_by": null
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tom gets his market wish in spirit here, a laid-back lunch spot with honest local flavours and no fuss.",
      "start_by": null
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The chocolate museum stays, because a food day without a little cacao would be a crime.",
      "start_by": null
    },
    {
      "poi_id": "p14",
      "kind": "meal",
      "must_do_id": null,
      "note": "We finish with a proper sit-down dinner at Cicciolina, where the day slows into a warm, well-fed evening.",
      "start_by": null
    }
  ]
}
